D[54] = dict(title='دعا برای برطرف شدن اندوه‌ها', sub='گشایش غم و اندوه، با آیت‌الکرسی و سه قل',
 intro_ar='وَكَانَ مِنْ دُعَائِهِ عَلَيْهِ السَّلَامُ فِي اسْتِكْشَافِ الْهُمُومِ',
 intro_fa='از دعاهای امام سجاد (ع) در درخواستِ برطرف شدن اندوه‌ها',
 p=[
('يَا فَارِجَ الْهَمِّ، وَكَاشِفَ الْغَمِّ، يَا رَحْمٰنَ الدُّنْيَا وَالْآخِرَةِ وَرَحِيمَهُمَا، صَلِّ عَلَى مُحَمَّدٍ وَآلِ مُحَمَّدٍ، وَافْرُجْ هَمِّي، وَاكْشِفْ غَمِّي،',
 'ای گشایندهٔ اندوه، و ای برطرف‌کنندهٔ غم، ای بخشایندهٔ دنیا و آخرت و مهربانِ هر دو، بر محمد و خاندان محمد درود فرست، و اندوهم را بگشا، و غمم را برطرف کن.'),
('يَا وَاحِدُ يَا أَحَدُ يَا صَمَدُ، يَا مَنْ لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَهُ كُفُواً أَحَدٌ، اعْصِمْنِي وَطَهِّرْنِي، وَاذْهَبْ بِبَلِيَّتِي.',
 'ای یکتا، ای یگانه، ای بی‌نیاز، ای کسی که نزاده و زاده نشده و هیچ کس همتای او نیست، مرا نگاه دار و پاکم کن، و گرفتاری‌ام را ببر.'),
('(وَاقْرَأْ آيَةَ الْكُرْسِيِّ وَالْمُعَوِّذَتَيْنِ وَقُلْ هُوَ اللّٰهُ أَحَدٌ، وَقُلْ:)',
 '(در اینجا آیت‌الکرسی، سورهٔ فلق، سورهٔ ناس و سورهٔ اخلاص را بخوان؛ سپس بگو:)'),
('اللّٰهُمَّ إِنِّي أَسْأَلُكَ سُؤَالَ مَنِ اشْتَدَّتْ فَاقَتُهُ، وَضَعُفَتْ قُوَّتُهُ، وَكَثُرَتْ ذُنُوبُهُ، سُؤَالَ مَنْ لَا يَجِدُ لِفَاقَتِهِ مُغِيثاً، وَلَا لِضَعْفِهِ مُقَوِّياً، وَلَا لِذَنْبِهِ غَافِراً غَيْرَكَ، يَا ذَا الْجَلَالِ وَالْإِكْرَامِ،',
 'خدایا، از تو درخواست می‌کنم، درخواستِ کسی که نیازش سخت شده، و نیرویش سست گشته، و گناهانش بسیار شده؛ درخواستِ کسی که برای نیازش فریادرسی، و برای ناتوانی‌اش نیروبخشی، و برای گناهش آمرزنده‌ای جز تو نمی‌یابد؛ ای صاحب شکوه و بزرگواری.'),
('أَسْأَلُكَ عَمَلاً تُحِبُّ بِهِ مَنْ عَمِلَ بِهِ، وَيَقِيناً تَنْفَعُ بِهِ مَنِ اسْتَيْقَنَ بِهِ حَقَّ الْيَقِينِ فِي نَفَاذِ أَمْرِكَ.',
 'از تو کاری می‌خواهم که هر کس آن را انجام دهد، به سبب آن دوستش بداری؛ و یقینی که هر کس با یقینِ راستین به روان بودن فرمانت به آن یقین کند، با آن سودش رسانی.'),
('اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِ مُحَمَّدٍ، وَاقْبِضْ عَلَى الصِّدْقِ نَفْسِي، وَاقْطَعْ مِنَ الدُّنْيَا حَاجَتِي، وَاجْعَلْ فِيمَا عِنْدَكَ رَغْبَتِي شَوْقاً إِلَى لِقَائِكَ، وَهَبْ لِي صِدْقَ التَّوَكُّلِ عَلَيْكَ.',
 'خدایا، بر محمد و خاندان محمد درود فرست، و جانم را در حالِ راستی بگیر، و نیازم را از دنیا ببُر، و از سرِ شوق به دیدارت، اشتیاقم را به آنچه نزد توست قرار ده، و توکلِ راستین بر خودت را به من ببخش.'),
('أَسْأَلُكَ مِنْ خَيْرِ كِتَابٍ قَدْ خَلَا، وَأَعُوذُ بِكَ مِنْ شَرِّ كِتَابٍ قَدْ خَلَا، أَسْأَلُكَ خَوْفَ الْعَابِدِينَ لَكَ، وَعِبَادَةَ الْخَاشِعِينَ لَكَ، وَيَقِينَ الْمُتَوَكِّلِينَ عَلَيْكَ، وَتَوَكُّلَ الْمُؤْمِنِينَ عَلَيْكَ.',
 'از تو خیرِ سرنوشتی را که پیش‌تر نوشته شده می‌خواهم، و از شرّ سرنوشتی که پیش‌تر نوشته شده به تو پناه می‌برم. از تو ترسِ عبادت‌کنندگانت، و عبادتِ فروتنانت، و یقینِ توکل‌کنندگان بر تو، و توکلِ مؤمنان بر تو را می‌خواهم.'),
('اللّٰهُمَّ اجْعَلْ رَغْبَتِي فِي مَسْأَلَتِي مِثْلَ رَغْبَةِ أَوْلِيَائِكَ فِي مَسَائِلِهِمْ، وَرَهْبَتِي مِثْلَ رَهْبَةِ أَوْلِيَائِكَ، وَاسْتَعْمِلْنِي فِي مَرْضَاتِكَ عَمَلاً لَا أَتْرُكُ مَعَهُ شَيْئاً مِنْ دِينِكَ مَخَافَةَ أَحَدٍ مِنْ خَلْقِكَ.',
 'خدایا، اشتیاقم را در درخواستم مانند اشتیاق دوستانت در درخواست‌هایشان، و بیمم را مانند بیم دوستانت قرار ده، و مرا در راه خشنودی‌ات به کاری بگمار که با آن، از ترس هیچ یک از آفریدگانت، چیزی از دینت را رها نکنم.'),
('اللّٰهُمَّ هَذِهِ حَاجَتِي، فَأَعْظِمْ فِيهَا رَغْبَتِي، وَأَظْهِرْ فِيهَا عُذْرِي، وَلَقِّنِّي فِيهَا حُجَّتِي، وَعَافِ فِيهَا جَسَدِي.',
 'خدایا، این نیاز من است؛ پس اشتیاقم را در آن بزرگ گردان، و عذرم را در آن آشکار کن، و دلیلم را در آن به من بیاموز، و تنم را در آن سلامت دار.'),
('اللّٰهُمَّ مَنْ أَصْبَحَ لَهُ ثِقَةٌ أَوْ رَجَاءٌ غَيْرُكَ، فَقَدْ أَصْبَحْتُ وَأَنْتَ ثِقَتِي وَرَجَائِي فِي الْأُمُورِ كُلِّهَا، فَاقْضِ لِي بِخَيْرِهَا عَاقِبَةً، وَنَجِّنِي مِنْ مُضِلَّاتِ الْفِتَنِ، بِرَحْمَتِكَ يَا أَرْحَمَ الرَّاحِمِينَ،',
 'خدایا، اگر کسی صبح کرده و تکیه‌گاه یا امیدی جز تو دارد، من صبح کرده‌ام در حالی که تو در همهٔ کارها تکیه‌گاه و امید منی؛ پس برایم به آنچه سرانجامش بهتر است حکم کن، و مرا از فتنه‌های گمراه‌کننده نجات ده؛ به رحمتت، ای مهربان‌ترین مهربانان.'),
('وَصَلَّى اللّٰهُ عَلَى سَيِّدِنَا مُحَمَّدٍ رَسُولِ اللّٰهِ الْمُصْطَفَى، وَعَلَى آلِهِ الطَّاهِرِينَ.',
 'و درود خدا بر سرور ما محمد، فرستادهٔ برگزیدهٔ خدا، و بر خاندان پاکش.'),
])
D[23] = dict(title='دعای عافیت', sub='تندرستی، امنیت و پناه از هر بدخواه',
 intro_ar='وَكَانَ مِنْ دُعَائِهِ عَلَيْهِ السَّلَامُ إِذَا سَأَلَ اللّٰهَ الْعَافِيَةَ وَشُكْرَهَا',
 intro_fa='از دعاهای امام سجاد (ع) هنگامی که از خدا عافیت و سپاس‌گزاری بر آن را می‌خواست',
 p=[
('اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَأَلْبِسْنِي عَافِيَتَكَ، وَجَلِّلْنِي عَافِيَتَكَ، وَحَصِّنِّي بِعَافِيَتِكَ، وَأَكْرِمْنِي بِعَافِيَتِكَ، وَأَغْنِنِي بِعَافِيَتِكَ، وَتَصَدَّقْ عَلَيَّ بِعَافِيَتِكَ، وَهَبْ لِي عَافِيَتَكَ، وَأَفْرِشْنِي عَافِيَتَكَ، وَأَصْلِحْ لِي عَافِيَتَكَ، وَلَا تُفَرِّقْ بَيْنِي وَبَيْنَ عَافِيَتِكَ فِي الدُّنْيَا وَالْآخِرَةِ.',
 'خدایا، بر محمد و خاندانش درود فرست، و عافیتت را بر من بپوشان، و با عافیتت سراپایم را فرا گیر، و با عافیتت مرا در پناه نگه دار، و با عافیتت گرامی‌ام بدار، و با عافیتت بی‌نیازم کن، و عافیتت را بر من صدقه ده، و عافیتت را به من ببخش، و عافیتت را بستر من کن، و عافیتت را برایم سامان ده، و در دنیا و آخرت میان من و عافیتت جدایی مینداز.'),
('اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَعَافِنِي عَافِيَةً كَافِيَةً شَافِيَةً عَالِيَةً نَامِيَةً، عَافِيَةً تُوَلِّدُ فِي بَدَنِي الْعَافِيَةَ، عَافِيَةَ الدُّنْيَا وَالْآخِرَةِ،',
 'خدایا، بر محمد و خاندانش درود فرست، و مرا عافیتی ده بسنده، شفابخش، والا و فزاینده؛ عافیتی که در تنم عافیت بزاید؛ عافیت دنیا و آخرت.'),
('وَامْنُنْ عَلَيَّ بِالصِّحَّةِ وَالْأَمْنِ وَالسَّلَامَةِ فِي دِينِي وَبَدَنِي، وَالْبَصِيرَةِ فِي قَلْبِي، وَالنَّفَاذِ فِي أُمُورِي، وَالْخَشْيَةِ لَكَ، وَالْخَوْفِ مِنْكَ، وَالْقُوَّةِ عَلَى مَا أَمَرْتَنِي بِهِ مِنْ طَاعَتِكَ، وَالِاجْتِنَابِ لِمَا نَهَيْتَنِي عَنْهُ مِنْ مَعْصِيَتِكَ.',
 'و بر من منت گذار با تندرستی و امنیت و سلامت در دین و تنم، و بینش در دلم، و پیش رفتن در کارهایم، و خشیت برای تو، و ترس از تو، و نیرو بر طاعتی که به آن فرمانم دادی، و دوری از نافرمانی‌ای که از آن بازم داشتی.'),
('اللّٰهُمَّ وَامْنُنْ عَلَيَّ بِالْحَجِّ وَالْعُمْرَةِ، وَزِيَارَةِ قَبْرِ رَسُولِكَ، صَلَوَاتُكَ عَلَيْهِ وَرَحْمَتُكَ وَبَرَكَاتُكَ عَلَيْهِ وَعَلَى آلِهِ، وَآلِ رَسُولِكَ عَلَيْهِمُ السَّلَامُ، أَبَداً مَا أَبْقَيْتَنِي، فِي عَامِي هَذَا وَفِي كُلِّ عَامٍ، وَاجْعَلْ ذَلِكَ مَقْبُولاً مَشْكُوراً، مَذْكُوراً لَدَيْكَ، مَذْخُوراً عِنْدَكَ،',
 'خدایا، و بر من منت گذار با حج و عمره، و زیارت مزار پیامبرت، که درودها و رحمت و برکت‌هایت بر او و خاندانش باد، و [زیارت] خاندان پیامبرت، که سلام بر آنان باد؛ همیشه تا وقتی مرا زنده می‌داری، در امسال و در هر سال؛ و آن را پذیرفته و سپاس‌شده، و نزد خودت یادشده و اندوخته قرار ده.'),
('وَأَنْطِقْ بِحَمْدِكَ وَشُكْرِكَ وَذِكْرِكَ وَحُسْنِ الثَّنَاءِ عَلَيْكَ لِسَانِي، وَاشْرَحْ لِمَرَاشِدِ دِينِكَ قَلْبِي،',
 'و زبانم را به ستایش و سپاس و یاد تو و ثنای نیکو بر تو گویا کن، و دلم را برای راه‌های رشدِ دینت گشاده گردان.'),
('وَأَعِذْنِي وَذُرِّيَّتِي مِنَ الشَّيْطَانِ الرَّجِيمِ، وَمِنْ شَرِّ السَّامَّةِ وَالْهَامَّةِ وَالْعَامَّةِ وَاللَّامَّةِ، وَمِنْ شَرِّ كُلِّ شَيْطَانٍ مَرِيدٍ، وَمِنْ شَرِّ كُلِّ سُلْطَانٍ عَنِيدٍ، وَمِنْ شَرِّ كُلِّ مُتْرَفٍ حَفِيدٍ،',
 'و مرا و فرزندانم را از شیطان رانده‌شده پناه ده؛ و از شرّ جانوران زهردار، و حشرات گزنده، و بلاهای همگانی، و چشم‌زخم؛ و از شرّ هر شیطان سرکش، و از شرّ هر فرمانروای ستیزه‌جو، و از شرّ هر خوش‌گذرانِ برخوردار از یاوران.'),
('وَمِنْ شَرِّ كُلِّ ضَعِيفٍ وَشَدِيدٍ، وَمِنْ شَرِّ كُلِّ شَرِيفٍ وَوَضِيعٍ، وَمِنْ شَرِّ كُلِّ صَغِيرٍ وَكَبِيرٍ، وَمِنْ شَرِّ كُلِّ قَرِيبٍ وَبَعِيدٍ، وَمِنْ شَرِّ كُلِّ مَنْ نَصَبَ لِرَسُولِكَ وَلِأَهْلِ بَيْتِهِ حَرْباً مِنَ الْجِنِّ وَالْإِنْسِ، وَمِنْ شَرِّ كُلِّ دَابَّةٍ أَنْتَ آخِذٌ بِنَاصِيَتِهَا، إِنَّكَ عَلَى صِرَاطٍ مُسْتَقِيمٍ.',
 'و از شرّ هر ناتوان و نیرومند، و از شرّ هر بلندپایه و فرومایه، و از شرّ هر کوچک و بزرگ، و از شرّ هر نزدیک و دور، و از شرّ هر کس از جن و انس که با پیامبرت و خاندانش به جنگ برخاسته، و از شرّ هر جنبنده‌ای که اختیارش به دست توست؛ که تو بر راه راستی.'),
('اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَمَنْ أَرَادَنِي بِسُوءٍ فَاصْرِفْهُ عَنِّي، وَادْحَرْ عَنِّي مَكْرَهُ، وَادْرَأْ عَنِّي شَرَّهُ، وَرُدَّ كَيْدَهُ فِي نَحْرِهِ،',
 'خدایا، بر محمد و خاندانش درود فرست، و هر کس با من قصد بدی دارد او را از من بگردان، و نیرنگش را از من دور کن، و شرّش را از من بازدار، و حیله‌اش را به گلوی خودش بازگردان.'),
('وَاجْعَلْ بَيْنَ يَدَيْهِ سَدّاً حَتَّى تُعْمِيَ عَنِّي بَصَرَهُ، وَتُصِمَّ عَنْ ذِكْرِي سَمْعَهُ، وَتُقْفِلَ دُونَ إِخْطَارِي قَلْبَهُ، وَتُخْرِسَ عَنِّي لِسَانَهُ، وَتَقْمَعَ رَأْسَهُ، وَتُذِلَّ عِزَّهُ، وَتَكْسِرَ جَبَرُوتَهُ، وَتُذِلَّ رَقَبَتَهُ، وَتَفْسَخَ كِبْرَهُ،',
 'و پیش رویش سدّی قرار ده تا چشمش را از [دیدن] من ببندی، و گوشش را از شنیدن نام من ناشنوا کنی، و دلش را از به یاد آوردن من قفل کنی، و زبانش را از [بدگویی] من بازداری، و سرکشی‌اش را بکوبی، و عزتش را خوار کنی، و زورگویی‌اش را بشکنی، و گردنش را فروتن کنی، و تکبرش را درهم شکنی.'),
('وَتُؤْمِنَنِي مِنْ جَمِيعِ ضَرِّهِ وَشَرِّهِ، وَغَمْزِهِ وَهَمْزِهِ وَلَمْزِهِ، وَحَسَدِهِ وَعَدَاوَتِهِ، وَحَبَائِلِهِ وَمَصَائِدِهِ، وَرَجِلِهِ وَخَيْلِهِ، إِنَّكَ عَزِيزٌ قَدِيرٌ.',
 'و مرا از همهٔ زیان و شرّش، و طعنه و بدگویی و عیب‌جویی‌اش، و حسد و دشمنی‌اش، و دام‌ها و تله‌هایش، و پیاده‌ها و سواره‌هایش ایمن داری؛ که تو شکست‌ناپذیر و توانایی.'),
])
D[21] = dict(title='دعا هنگام اندوه و نگرانی از گناه', sub='تنهایی، ترس و پناه بردن به خدا',
 intro_ar='وَكَانَ مِنْ دُعَائِهِ عَلَيْهِ السَّلَامُ إِذَا حَزَنَهُ أَمْرٌ وَأَهَمَّتْهُ الْخَطَايَا',
 intro_fa='از دعاهای امام سجاد (ع) هنگامی که کاری اندوهگینش می‌کرد و گناهان نگرانش می‌ساخت',
 p=[
('اللّٰهُمَّ يَا كَافِيَ الْفَرْدِ الضَّعِيفِ، وَوَاقِيَ الْأَمْرِ الْمَخُوفِ، أَفْرَدَتْنِي الْخَطَايَا فَلَا صَاحِبَ مَعِي، وَضَعُفْتُ عَنْ غَضَبِكَ فَلَا مُؤَيِّدَ لِي، وَأَشْرَفْتُ عَلَى خَوْفِ لِقَائِكَ فَلَا مُسَكِّنَ لِرَوْعَتِي،',
 'خدایا، ای کفایت‌کنندهٔ تنهای ناتوان، و ای نگه‌دارنده از کار هراسناک، گناهان مرا تنها کرده‌اند و همراهی ندارم، و در برابر خشم تو ناتوانم و پشتیبانی ندارم، و به ترسِ دیدارت نزدیک شده‌ام و کسی نیست که هراسم را آرام کند.'),
('وَمَنْ يُؤْمِنُنِي مِنْكَ وَأَنْتَ أَخَفْتَنِي، وَمَنْ يُسَاعِدُنِي وَأَنْتَ أَفْرَدْتَنِي، وَمَنْ يُقَوِّينِي وَأَنْتَ أَضْعَفْتَنِي.',
 'و چه کسی مرا از تو ایمن کند، حال آنکه تو مرا ترسانده‌ای؟ و چه کسی یاری‌ام دهد، حال آنکه تو تنهایم گذاشته‌ای؟ و چه کسی نیرومندم کند، حال آنکه تو ناتوانم ساخته‌ای؟'),
('لَا يُجِيرُ يَا إِلَهِي إِلَّا رَبٌّ عَلَى مَرْبُوبٍ، وَلَا يُؤْمِنُ إِلَّا غَالِبٌ عَلَى مَغْلُوبٍ، وَلَا يُعِينُ إِلَّا طَالِبٌ عَلَى مَطْلُوبٍ،',
 'معبودا، جز پروردگار به پرورده‌اش پناه نمی‌دهد، و جز چیره به مغلوبش امان نمی‌دهد، و جز جوینده کسی بر جسته‌شده یاری نمی‌رساند.'),
('وَبِيَدِكَ يَا إِلَهِي جَمِيعُ ذَلِكَ السَّبَبِ، وَإِلَيْكَ الْمَفَرُّ وَالْمَهْرَبُ، فَصَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَأَجِرْ هَرَبِي، وَأَنْجِحْ مَطْلَبِي.',
 'و معبودا، همهٔ این رشته‌ها به دست توست، و گریزگاه و پناه به سوی توست؛ پس بر محمد و خاندانش درود فرست، و گریختنم [به سوی تو] را پناه ده، و خواسته‌ام را برآور.'),
('اللّٰهُمَّ إِنَّكَ إِنْ صَرَفْتَ عَنِّي وَجْهَكَ الْكَرِيمَ، أَوْ مَنَعْتَنِي فَضْلَكَ الْجَسِيمَ، أَوْ حَظَرْتَ عَلَيَّ رِزْقَكَ، أَوْ قَطَعْتَ عَنِّي سَبَبَكَ، لَمْ أَجِدِ السَّبِيلَ إِلَى شَيْءٍ مِنْ أَمَلِي غَيْرَكَ، وَلَمْ أَقْدِرْ عَلَى مَا عِنْدَكَ بِمَعُونَةِ سِوَاكَ،',
 'خدایا، اگر روی کریمت را از من بگردانی، یا فضل بزرگت را از من بازداری، یا روزی‌ات را بر من ببندی، یا رشتهٔ پیوندت را از من ببری، به هیچ چیز از آرزویم راهی جز تو نمی‌یابم، و با یاری کسی جز تو به آنچه نزد توست دست نمی‌یابم؛'),
('فَإِنِّي عَبْدُكَ وَفِي قَبْضَتِكَ، نَاصِيَتِي بِيَدِكَ، لَا أَمْرَ لِي مَعَ أَمْرِكَ، مَاضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قَضَاؤُكَ، وَلَا قُوَّةَ لِي عَلَى الْخُرُوجِ مِنْ سُلْطَانِكَ، وَلَا أَسْتَطِيعُ مُجَاوَزَةَ قُدْرَتِكَ، وَلَا أَسْتَمِيلُ هَوَاكَ، وَلَا أَبْلُغُ رِضَاكَ، وَلَا أَنَالُ مَا عِنْدَكَ إِلَّا بِطَاعَتِكَ وَبِفَضْلِ رَحْمَتِكَ.',
 'زیرا من بندهٔ توام و در چنگ توام؛ اختیارم به دست توست؛ با فرمان تو مرا فرمانی نیست؛ حکمت دربارهٔ من روان است، و داوری‌ات دربارهٔ من عادلانه است؛ و مرا نیرویی برای بیرون رفتن از فرمانروایی‌ات نیست، و نمی‌توانم از قدرتت فراتر روم، و نمی‌توانم خواست تو را به سوی خود بگردانم، و به خشنودی‌ات نمی‌رسم، و به آنچه نزد توست دست نمی‌یابم، مگر با طاعتت و به فضل رحمتت.'),
('إِلَهِي أَصْبَحْتُ وَأَمْسَيْتُ عَبْداً دَاخِراً لَكَ، لَا أَمْلِكُ لِنَفْسِي نَفْعاً وَلَا ضَرّاً إِلَّا بِكَ، أَشْهَدُ بِذَلِكَ عَلَى نَفْسِي، وَأَعْتَرِفُ بِضَعْفِ قُوَّتِي وَقِلَّةِ حِيلَتِي، فَأَنْجِزْ لِي مَا وَعَدْتَنِي، وَتَمِّمْ لِي مَا آتَيْتَنِي،',
 'معبودا، صبح و شام کردم در حالی که بنده‌ای فروتن برای توام؛ جز به [یاری] تو برای خودم سود و زیانی در اختیار ندارم؛ به این بر خود گواهی می‌دهم، و به سستی نیرو و کمی چاره‌ام اعتراف می‌کنم؛ پس آنچه را به من وعده دادی برایم انجام ده، و آنچه را به من دادی برایم کامل کن؛'),
('فَإِنِّي عَبْدُكَ الْمِسْكِينُ الْمُسْتَكِينُ الضَّعِيفُ الضَّرِيرُ الذَّلِيلُ الْحَقِيرُ الْمَهِينُ الْفَقِيرُ الْخَائِفُ الْمُسْتَجِيرُ.',
 'زیرا من بندهٔ بیچاره، فروتن، ناتوان، درمانده، خوار، ناچیز، بی‌مقدار، نیازمند، ترسان و پناه‌جوی توام.'),
('اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَلَا تَجْعَلْنِي نَاسِياً لِذِكْرِكَ فِيمَا أَوْلَيْتَنِي، وَلَا غَافِلاً لِإِحْسَانِكَ فِيمَا أَبْلَيْتَنِي، وَلَا آيِساً مِنْ إِجَابَتِكَ لِي وَإِنْ أَبْطَأَتْ عَنِّي، فِي سَرَّاءَ كُنْتُ أَوْ ضَرَّاءَ، أَوْ شِدَّةٍ أَوْ رَخَاءٍ، أَوْ عَافِيَةٍ أَوْ بَلَاءٍ، أَوْ بُؤْسٍ أَوْ نَعْمَاءَ، أَوْ جِدَةٍ أَوْ لَأْوَاءَ، أَوْ فَقْرٍ أَوْ غِنًى.',
 'خدایا، بر محمد و خاندانش درود فرست، و مرا در نعمت‌هایی که به من دادی فراموش‌کار یاد تو، و در آنچه به آن آزمودی‌ام غافل از نیکی‌ات، و از پاسخ دادنت به من، هرچند دیر کند، ناامید قرار مده؛ چه در شادی باشم یا در گرفتاری، در سختی یا آسایش، در عافیت یا بلا، در تنگدستی یا نعمت، در توانگری یا تنگنا، در فقر یا بی‌نیازی.'),
('اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَاجْعَلْ ثَنَائِي عَلَيْكَ، وَمَدْحِي إِيَّاكَ، وَحَمْدِي لَكَ فِي كُلِّ حَالَاتِي، حَتَّى لَا أَفْرَحَ بِمَا آتَيْتَنِي مِنَ الدُّنْيَا، وَلَا أَحْزَنَ عَلَى مَا مَنَعْتَنِي فِيهَا،',
 'خدایا، بر محمد و خاندانش درود فرست، و ثنا و ستایش و سپاسم را برای تو در همهٔ حالاتم [پیوسته] قرار ده، تا به آنچه از دنیا به من دادی سرمست نشوم، و بر آنچه از آن بازم داشتی اندوهگین نگردم.'),
('وَأَشْعِرْ قَلْبِي تَقْوَاكَ، وَاسْتَعْمِلْ بَدَنِي فِيمَا تَقْبَلُهُ مِنِّي، وَاشْغَلْ بِطَاعَتِكَ نَفْسِي عَنْ كُلِّ مَا يَرِدُ عَلَيَّ، حَتَّى لَا أُحِبَّ شَيْئاً مِنْ سُخْطِكَ، وَلَا أَسْخَطَ شَيْئاً مِنْ رِضَاكَ.',
 'و پروای خودت را با دلم همراه کن، و تنم را در کاری به کار گیر که از من بپذیری، و جانم را با طاعتت از هر چه بر من وارد می‌شود سرگرم کن، تا هیچ چیز از آنچه تو را خشمگین می‌کند دوست نداشته باشم، و از هیچ چیز که تو را خشنود می‌کند ناخشنود نباشم.'),
('اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَفَرِّغْ قَلْبِي لِمَحَبَّتِكَ، وَاشْغَلْهُ بِذِكْرِكَ، وَانْعَشْهُ بِخَوْفِكَ وَبِالْوَجَلِ مِنْكَ، وَقَوِّهِ بِالرَّغْبَةِ إِلَيْكَ، وَأَمِلْهُ إِلَى طَاعَتِكَ، وَأَجْرِ بِهِ فِي أَحَبِّ السُّبُلِ إِلَيْكَ، وَذَلِّلْهُ بِالرَّغْبَةِ فِيمَا عِنْدَكَ أَيَّامَ حَيَاتِي كُلَّهَا.',
 'خدایا، بر محمد و خاندانش درود فرست، و دلم را برای محبتت فارغ کن، و آن را به یادت سرگرم ساز، و با ترس و هراس از تو زنده‌اش بدار، و با اشتیاق به سویت نیرومندش کن، و به سوی طاعتت متمایلش ساز، و آن را در محبوب‌ترین راه‌ها نزد خودت روان کن، و در همهٔ روزهای زندگی‌ام با اشتیاق به آنچه نزد توست رامش گردان.'),
('وَاجْعَلْ تَقْوَاكَ مِنَ الدُّنْيَا زَادِي، وَإِلَى رَحْمَتِكَ رِحْلَتِي، وَفِي مَرْضَاتِكَ مَدْخَلِي، وَاجْعَلْ فِي جَنَّتِكَ مَثْوَايَ، وَهَبْ لِي قُوَّةً أَحْتَمِلُ بِهَا جَمِيعَ مَرْضَاتِكَ، وَاجْعَلْ فِرَارِي إِلَيْكَ، وَرَغْبَتِي فِيمَا عِنْدَكَ،',
 'و پروای خودت را توشهٔ من از دنیا، و رحمتت را مقصد سفرم، و خشنودی‌ات را جای درآمدنم قرار ده، و جایگاهم را در بهشتت بگذار، و نیرویی به من ببخش که با آن همهٔ آنچه تو را خشنود می‌کند بر دوش کشم، و گریزم را به سوی خودت، و اشتیاقم را به آنچه نزد توست قرار ده.'),
('وَأَلْبِسْ قَلْبِيَ الْوَحْشَةَ مِنْ شِرَارِ خَلْقِكَ، وَهَبْ لِيَ الْأُنْسَ بِكَ وَبِأَوْلِيَائِكَ وَأَهْلِ طَاعَتِكَ، وَلَا تَجْعَلْ لِفَاجِرٍ وَلَا كَافِرٍ عَلَيَّ مِنَّةً، وَلَا لَهُ عِنْدِي يَداً، وَلَا بِي إِلَيْهِمْ حَاجَةً،',
 'و بر دلم جامهٔ دوری از بدترین آفریدگانت بپوشان، و انس با خودت و دوستانت و اهل طاعتت را به من ببخش، و برای هیچ بدکار و کافری بر من منتی، و نزد من حق نعمتی، و مرا به آنان نیازی قرار مده.'),
('بَلِ اجْعَلْ سُكُونَ قَلْبِي، وَأُنْسَ نَفْسِي، وَاسْتِغْنَائِي وَكِفَايَتِي بِكَ وَبِخِيَارِ خَلْقِكَ.',
 'بلکه آرامش دلم، و انس جانم، و بی‌نیازی و کفایتم را به خودت و به بهترین آفریدگانت قرار ده.'),
('اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَاجْعَلْنِي لَهُمْ قَرِيناً، وَاجْعَلْنِي لَهُمْ نَصِيراً، وَامْنُنْ عَلَيَّ بِشَوْقٍ إِلَيْكَ، وَبِالْعَمَلِ لَكَ بِمَا تُحِبُّ وَتَرْضَى، إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، وَذَلِكَ عَلَيْكَ يَسِيرٌ.',
 'خدایا، بر محمد و خاندانش درود فرست، و مرا هم‌نشین و یاور آنان قرار ده، و با شوق به خودت، و کار کردن برای تو به آنچه دوست داری و می‌پسندی، بر من منت گذار؛ که تو بر هر چیز توانایی، و این بر تو آسان است.'),
])
